export type AppEvent =
  | { type: 'click'; x: number; y: number }
  | { type: 'keydown'; key: string }

export function describe(event: AppEvent): string {
  switch (event.type) {
    case 'click':
      return `click ${event.x},${event.y}`
    case 'keydown':
      return `keydown ${event.key}`
  }
}

